solution.solution.cpp:
#include <cstdint>
#include <format>
#include <string>

using HRESULT = std::int32_t;

bool succeeded(HRESULT hr) { return hr >= 0; }
bool failed(HRESULT hr) { return hr < 0; }

HRESULT hresultFromWin32(std::uint32_t error)
{
    if (static_cast<HRESULT>(error) <= 0) return static_cast<HRESULT>(error);
    return static_cast<HRESULT>((error & 0xFFFFu) | (7u << 16) | 0x80000000u);
}

struct HrParts { bool failure; unsigned facility; unsigned code; };

HrParts splitHresult(HRESULT hr)
{
    const auto bits{ static_cast<std::uint32_t>(hr) };
    return { (bits >> 31) != 0, (bits >> 16) & 0x7FFu, bits & 0xFFFFu };
}

std::string describeHresult(HRESULT hr)
{
    switch (static_cast<std::uint32_t>(hr))
    {
    case 0x00000000u: return "S_OK";
    case 0x00000001u: return "S_FALSE";
    case 0x80004005u: return "E_FAIL";
    case 0x80070057u: return "E_INVALIDARG";
    case 0x8007000Eu: return "E_OUTOFMEMORY";
    case 0x80070005u: return "E_ACCESSDENIED";
    default: break;
    }
    const HrParts parts{ splitHresult(hr) };
    if (parts.failure && parts.facility == 7) return "Win32 error " + std::to_string(parts.code);
    return std::format("HRESULT 0x{:08X}", static_cast<std::uint32_t>(hr));
}

std::string ntSeverity(std::uint32_t status)
{
    switch (status >> 30)
    {
    case 0: return "success";
    case 1: return "information";
    case 2: return "warning";
    default: return "error";
    }
}

unitTests:
HRESULT hr(std::uint32_t bits) { return static_cast<HRESULT>(bits); }
TEST("success and failure") {
    CHECK(succeeded(0) && succeeded(1) && !failed(1));
    CHECK(failed(hr(0x80004005)) && !succeeded(hr(0x80004005)));
    CHECK(succeeded(hr(0x0004000A)));
}
TEST("Win32 codes as HRESULTs") {
    CHECK_EQ(hresultFromWin32(87), hr(0x80070057));
    CHECK_EQ(hresultFromWin32(2), hr(0x80070002));
    CHECK_EQ(hresultFromWin32(0), 0);
    CHECK_EQ(hresultFromWin32(0x80070005), hr(0x80070005));
    CHECK_EQ(hresultFromWin32(0x12345), hr(0x80072345));
}
TEST("splitting the fields") {
    const HrParts a{ splitHresult(hr(0x80070057)) };
    CHECK(a.failure && a.facility == 7 && a.code == 87);
    const HrParts b{ splitHresult(hr(0x800401F0)) };
    CHECK(b.failure && b.facility == 4 && b.code == 0x1F0);
    const HrParts c{ splitHresult(1) };
    CHECK(!c.failure && c.facility == 0 && c.code == 1);
}
TEST("describing") {
    CHECK_EQ(describeHresult(0), std::string("S_OK"));
    CHECK_EQ(describeHresult(1), std::string("S_FALSE"));
    CHECK_EQ(describeHresult(hr(0x80004005)), std::string("E_FAIL"));
    CHECK_EQ(describeHresult(hr(0x80070057)), std::string("E_INVALIDARG"));
    CHECK_EQ(describeHresult(hr(0x8007000E)), std::string("E_OUTOFMEMORY"));
    CHECK_EQ(describeHresult(hr(0x80070005)), std::string("E_ACCESSDENIED"));
    CHECK_EQ(describeHresult(hr(0x80070002)), std::string("Win32 error 2"));
    CHECK_EQ(describeHresult(hresultFromWin32(1223)), std::string("Win32 error 1223"));
    CHECK_EQ(describeHresult(hr(0x800401F0)), std::string("HRESULT 0x800401F0"));
    CHECK_EQ(describeHresult(hr(0x00070002)), std::string("HRESULT 0x00070002"));
}
TEST("NTSTATUS severity") {
    CHECK_EQ(ntSeverity(0), std::string("success"));
    CHECK_EQ(ntSeverity(0x40000000), std::string("information"));
    CHECK_EQ(ntSeverity(0x80000005), std::string("warning"));
    CHECK_EQ(ntSeverity(0xC0000005), std::string("error"));
    CHECK_EQ(ntSeverity(0x3FFFFFFF), std::string("success"));
}

